(()=>{const r=__shellReview,m=r.motion,$=id=>document.getElementById(id);let n=performance.now();const tick=c=>{for(let i=0;i<c;i++)m.update(n+=50);};const snapshot=()=>JSON.stringify({state:m.state,camera:r.camera.position.toArray(),target:r.controls.target.toArray(),zoom:r.camera.zoom,layout:r.inspect().layoutMode,selected:r.inspect().selected,parts:m.inspect()});const results=[];
for(const action of ['shoot','reload','auto','spread','clay']){m.reset();$('cut').click();if(action==='shoot')m.release();if(action==='reload')m.reload();if(action==='auto')$('auto').click();if(action==='spread'){$('spread').value=60;$('spread').dispatchEvent(new Event('input'));}if(action==='clay')$('clay').click();tick(20);for(const paused of [false,true]){m.state.paused=paused;for(const theme of ['light','dark']){const before=snapshot();r.setTheme(theme);if(snapshot()!==before)throw Error(action+' mutated on '+theme);}}results.push(action);if(action==='clay')$('clay').click();}
m.reset();$('cut').click();m.state.charge=1;tick(50);m.state.paused=true;r.setTheme('light');return {statePreserved:results,glassEmission:m.inspect().glassEmission,coreEmission:m.inspect().coreEmission};})()
